// Bundled Torah content contracts (src/data/*.json, generated by scripts/import-torah.ts).

export interface Syllable {
  text: string; // analysis form (normalised by havarotjs; display uses WordToken.text)
  stressed: boolean;
  reduced: boolean; // vocal sheva / hataf only
}

export interface WordToken {
  id: string; // stable token id, e.g. "Genesis.1.1.3" — used for audio alignment and highlighting
  text: string; // display form, exactly as in the edition (maqaf / sof pasuq included)
  paseqAfter: 'paseq' | 'legarmeh' | null;
  maqafToNext: boolean;
  consonants: string; // letters as written
  spoken: string; // letters of what is read aloud (perpetual qere applied)
  taamim: string[]; // functional te'amim (cantillation.ts ids)
  primary: string | null; // governing ta'am; null when joined to the next word by maqaf
  syllables: Syllable[] | null;
  stress: 'ultima' | 'penultima' | 'antepenultima' | null; // from te'amim placement
  letterSize?: 'large' | 'small'; // scribal large/small letter
}

export interface PhraseGroup {
  words: number[]; // indexes into VerseData.words: conjunctives followed by their disjunctive
  taam: string | null;
}

export interface VerseData {
  id: string; // "Genesis.1.1"
  chapter: number;
  verse: number;
  aliyah: number;
  text: string; // display text
  words: WordToken[];
  groups: PhraseGroup[];
  breakAfter: 'petucha' | 'setuma' | null;
  notes: string[]; // editorial notes from the edition (e.g. scroll spelling variants)
}

export interface PortionData {
  schemaVersion: 1;
  id: string;
  nameHe: string;
  book: string;
  range: string;
  aliyot: { n: number; from: string; to: string }[];
  source: { edition: string; license: string; url: string; retrievedAt: string; reviewStatus: 'pending' | 'approved' };
  verses: VerseData[];
}

export const verseId = (book: string, chapter: number, verse: number) => `${book}.${chapter}.${verse}`;
